mapper.select:
SELECT P.PBANC_SN AS pbancSn, P.PBANC_NM AS pbancNm, P.PBANC_STTS_CD AS pbancSttsCd, S.CD_NM AS pbancSttsNm FROM TB_BID_PBANC P LEFT JOIN TB_COM_CD S ON S.GROUP_CD = 'PBSTS' AND S.CD = P.PBANC_STTS_CD WHERE P.PBANC_STTS_CD IN ('PS030', 'PS040', 'PS050', 'PS060', 'PS070') AND P.SPRVSN_TEAM_SN IS NOT NULL
AND P.SPRVSN_TEAM_SN = #{teamSn}
ORDER BY DECODE(P.PBANC_STTS_CD, 'PS050', 1, 'PS060', 2, 'PS040', 3, 'PS030', 4, 5), P.BID_DDLN_DT DESC NULLS LAST, P.PBANC_SN DESC
